// Digital Asset Links — proves this domain owns the Android app package, so
// Mobile Wallet Adapter wallets (Phantom, Solflare) don't show an "app
// identity could not be verified" phishing warning during Connect Wallet.
// Fingerprint pulled from the signed release APK via:
//   keytool -printcert -jarfile build-*.apk
// Two statements are published deliberately during the v1.5.0 changeover.
//
// Certificate rotation is not supported by the Solana dApp Store, so v1.5.0 ships
// as a NEW app record under a NEW package name, and the old listing is only
// removed once the new one is live. That means both builds are installed in the
// wild at the same time, each signed by a different key. Digital Asset Links
// takes an array, and a wallet matches whichever statement fits the app that is
// actually calling — so publishing both keeps Connect Wallet verified on the old
// build instead of regressing it to "identity could not be verified" the moment
// this file is deployed.
//
// REMOVE the first (legacy) statement once the old dApp Store record is deleted
// and existing installs have moved over.
const ASSET_LINKS = [
  {
    // LEGACY — v1.2.0-v1.4.0, signed with the original auto-generated debug cert.
    // That key is unrecoverable, which is what forced the whole rename.
    relation: ["delegate_permission/common.handle_all_urls"],
    target: {
      namespace: "android_app",
      package_name: "net.relayshield.cryptoshield",
      sha256_cert_fingerprints: [
        "17:5D:AA:BC:4B:2C:CA:19:8B:AD:84:B2:52:6A:7C:AD:9B:22:4F:B5:FC:61:4F:EA:F9:40:B7:B8:04:5D:74:51",
      ],
    },
  },
  {
    // CURRENT — v1.5.0 onwards, signed with cryptoshield-release.keystore
    // (CN=RelayShield LLC), generated 2026-07-25. Fingerprint verified against
    // the built APK with `apksigner verify --print-certs` on 2026-08-01.
    relation: ["delegate_permission/common.handle_all_urls"],
    target: {
      namespace: "android_app",
      package_name: "net.relayshield.cryptoshieldmobile",
      sha256_cert_fingerprints: [
        "5F:72:93:7B:97:47:A3:62:2B:73:24:67:AF:32:4F:B1:84:74:CE:E6:0A:17:43:0E:84:C6:6A:D3:C6:09:D4:E8",
      ],
    },
  },
];

const OG_BANNER_B64 = "";


const APP_ICON_B64 = "";

const SHOT_DASHBOARD_B64 = "";

const SHOT_WALLETS_B64 = "";
export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/og-banner.png") {
      const bytes = Uint8Array.from(atob(OG_BANNER_B64), (c) => c.charCodeAt(0));
      return new Response(bytes, {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400",
        },
      });
    }

    const IMAGE_ROUTES = {
      "/icon.png": APP_ICON_B64,
      "/screenshots/dashboard.png": SHOT_DASHBOARD_B64,
      "/screenshots/wallets.png": SHOT_WALLETS_B64,
    };
    if (url.pathname in IMAGE_ROUTES) {
      const bytes = Uint8Array.from(atob(IMAGE_ROUTES[url.pathname]), (c) => c.charCodeAt(0));
      return new Response(bytes, {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400",
        },
      });
    }

    if (url.pathname === "/.well-known/assetlinks.json") {
      return new Response(JSON.stringify(ASSET_LINKS), {
        status: 200,
        headers: {
          "Content-Type": "application/json",
          "Cache-Control": "public, max-age=3600",
        },
      });
    }

    return new Response(HTML, {
      status: 200,
      headers: {
        "Content-Type": "text/html;charset=UTF-8",
        "Cache-Control": "public, max-age=300",
      },
    });
  },
};
